{
    "friendly_name": "owl_store_scene_2_1_curated_items",
    "language": "en",
    "variables": {
        "name": "Twill",
        "discount": "30"
    },
    "types": {
        "twilio/carousel": {
            "body": "Hey {{name}}! Here are your hand-picked items for this sale — {{discount}}% off today only.",
            "cards": [
                {
                    "title": "Owl Store Signature Hoodie",
                    "body": "Heavyweight brushed fleece. Fits every season.",
                    "media": "https://forge-assets-5378.twil.io/owl_store/carousel-hoodie-front.jpg",
                    "actions": [
                        {
                            "type": "QUICK_REPLY",
                            "id": "btn_2_1_hoodie",
                            "title": "Add to bag"
                        }
                    ]
                },
                {
                    "title": "Owl Store Trail Shoe",
                    "body": "Lightweight grip sole. Ready for anything.",
                    "media": "https://forge-assets-5378.twil.io/owl_store/carousel-shoes-front.jpg",
                    "actions": [
                        {
                            "type": "QUICK_REPLY",
                            "id": "btn_2_1_shoes",
                            "title": "Add to bag"
                        }
                    ]
                }
            ]
        },
        "twilio/text": {
            "body": "Hey {{name}}! Here are your hand-picked items for this sale — {{discount}}% off today only.\n\n1. Owl Store Signature Hoodie — Heavyweight brushed fleece. Fits every season.\n2. Owl Store Trail Shoe — Lightweight grip sole. Ready for anything.\n\nReply HOODIE or SHOES to add an item to your bag."
        }
    }
}

{
    "friendly_name": "owl_store_scene_3_1_closest_store",
    "language": "en",
    "variables": {
        "name": "Twill",
        "store_name": "Owl Store SIGNAL",
        "store_address": "375 Beale St, San Francisco, CA 94105",
        "directions_url": "https://maps.app.goo.gl/tWMVXbAoktdRHDEy7"
    },
    "types": {
        "twilio/card": {
            "title": "📍 Your nearest Owl Store",
            "body": "{{store_name}} is ready for you, {{name}}.\n\n{{store_address}}",
            "media": [
                "https://forge-assets-5378.twil.io/owl_store/rich-card-sales.jpg"
            ],
            "actions": [
                {
                    "type": "URL",
                    "id": "btn_3_1_directions",
                    "title": "Get directions",
                    "url": "{{directions_url}}"
                }
            ]
        },
        "twilio/text": {
            "body": "{{name}}, your nearest Owl Store is {{store_name}} at {{store_address}}.\n\nDirections: {{directions_url}}"
        }
    }
}
